/**
 * Represents a tool invocation within a chat message.
 */
export interface IChatToolInvocation {
  /** The name of the tool that was invoked */
  toolName: string;
  /** Summary of the tool arguments (for display) */
  argsSummary?: string;
  /** Full arguments JSON (for expand view) */
  argsJson?: string;
  /** Summary of the result (for display) */
  resultSummary?: string;
  /** Full result JSON (for expand view) */
  resultJson?: string;
  /** Base64 image data if the result included an image */
  resultImageBase64?: string;
  /** Duration in milliseconds */
  durationMs?: number;
  /** Whether the tool invocation succeeded */
  success: boolean;
  /** Error message if failed */
  errorMessage?: string;
}

/**
 * Represents a single chat message entry.
 */
export interface IChatEntry {
  /** Unique ID for this entry */
  id: string;
  /** Role: user or assistant */
  role: "user" | "assistant";
  /** The message content */
  content: string;
  /** When the message was created */
  timestamp: Date;
  /** Tool invocations within this message (for assistant messages) */
  toolInvocations?: IChatToolInvocation[];
  /** Whether this message is still streaming */
  isStreaming?: boolean;
}

/**
 * Represents a chat session for a project.
 * Stored in a separate .mctchat file alongside the project.
 */
export interface IChatSession {
  /** Schema version for forward compatibility */
  schemaVersion: "1.0.0";
  /** The Copilot SDK session ID (may expire server-side) */
  sessionId?: string;
  /** The model used for this session */
  model?: string;
  /** All chat entries in order */
  entries: IChatEntry[];
  /** When the session was created */
  createdAt: Date;
  /** When the session was last updated */
  updatedAt: Date;
  /** Hash of the project schema when session started (for context freshness) */
  projectSchemaHash?: string;
}

/**
 * Summary of a project's content schema for context injection.
 * This is a lightweight version that doesn't bloat the context.
 */
export interface IProjectSchemaSummary {
  /** Whether this is a summarized version (AI should request full if needed) */
  isSummarized: true;
  /** Absolute path to the project folder */
  projectPath?: string;
  /** Project namespace */
  namespace?: string;
  /** Count of entity types */
  entityCount: number;
  /** Count of block types */
  blockCount: number;
  /** Count of item types */
  itemCount: number;
  /** Count of recipes */
  recipeCount: number;
  /** Count of loot tables */
  lootTableCount: number;
  /** Count of spawn rules */
  spawnRuleCount: number;
  /** List of entity IDs */
  entityIds?: string[];
  /** List of block IDs */
  blockIds?: string[];
  /** List of item IDs */
  itemIds?: string[];
  /** Detected entity traits (unique set) */
  detectedEntityTraits?: string[];
  /** Detected block traits (unique set) */
  detectedBlockTraits?: string[];
  /** Detected item traits (unique set) */
  detectedItemTraits?: string[];
  /** Recent validation issues (warnings/errors) */
  recentValidationIssues?: string[];
  /** Hint for AI to request full schema */
  fullSchemaAvailableViaTool: "getEffectiveContentSchema";
}

/**
 * Copilot authentication status.
 * The SDK handles CLI detection internally - errors will indicate if CLI is missing.
 */
export interface ICopilotAuthStatus {
  /** Whether the user is authenticated and ready to use Copilot */
  isAuthenticated: boolean;
  /** GitHub login name if authenticated */
  login?: string;
  /** Error message if auth check failed - may indicate CLI not installed, not authenticated, etc. */
  error?: string;
}

/**
 * Available model info from Copilot SDK.
 */
export interface ICopilotModel {
  /** Model ID (e.g., "gpt-4o", "claude-sonnet-4.5") */
  id: string;
  /** Display name */
  name: string;
  /** Whether this is the default model */
  isDefault?: boolean;
}

/**
 * Event data for streaming message deltas.
 */
export interface ICopilotMessageDelta {
  /** Session ID */
  sessionId: string;
  /** The delta content to append */
  deltaContent: string;
}

/**
 * Event data for tool invocation start.
 */
export interface ICopilotToolStart {
  /** Session ID */
  sessionId: string;
  /** Tool call ID */
  toolCallId: string;
  /** Tool name */
  toolName: string;
  /** Tool arguments (JSON string) */
  argsJson: string;
}

/**
 * Event data for tool invocation end.
 */
export interface ICopilotToolEnd {
  /** Session ID */
  sessionId: string;
  /** Tool call ID */
  toolCallId: string;
  /** Tool name */
  toolName: string;
  /** Result (JSON string) */
  resultJson: string;
  /** Base64-encoded image result if the tool returned one */
  resultImageBase64?: string;
  /** Duration in milliseconds */
  durationMs: number;
  /** Whether it succeeded */
  success: boolean;
  /** Error message if failed */
  errorMessage?: string;
}

/**
 * Event data for complete assistant message.
 */
export interface ICopilotMessage {
  /** Session ID */
  sessionId: string;
  /** The complete message */
  message: IChatEntry;
}

/**
 * Union type for all Copilot events sent from main to renderer.
 */
export type CopilotEvent =
  | { type: "message_delta"; data: ICopilotMessageDelta }
  | { type: "message"; data: ICopilotMessage }
  | { type: "tool_start"; data: ICopilotToolStart }
  | { type: "tool_end"; data: ICopilotToolEnd }
  | { type: "session_idle"; sessionId: string }
  | { type: "context_updated"; sessionId: string }
  | { type: "error"; sessionId: string; error: string };
